import unittest
from endpoint import handle
from pipeline import process


class FlowTest(unittest.TestCase):
    def test_endpoint_option(self):
        self.assertEqual(handle({'text': 'Hello', 'uppercase': True}), 'HELLO')

    def test_pipeline_option(self):
        self.assertEqual(process('Hello', uppercase=True), 'HELLO')

    def test_default(self):
        self.assertEqual(handle({'text': 'Hello'}), 'Hello')
        self.assertEqual(process('Hello'), 'Hello')

    def test_explicit_false(self):
        self.assertEqual(handle({'text': 'Hello', 'uppercase': False}), 'Hello')
